// Options controls static API metadata.
type Options struct {
	Version           string
	Logger            *slog.Logger
	HeartbeatInterval time.Duration
	Now               func() time.Time
}

// View is one coherent cache and authorization-policy generation.
type View struct {
	Store               *cache.Store
	Status              *statusmodel.Hub
	TokenDigests        [][sha256.Size]byte
	AllowedClients      []netip.Prefix
	CertificateNotAfter time.Time
	PollFullInterval    time.Duration
}

// ViewProvider returns the current coherent runtime generation for one request.
type ViewProvider func() View

// API routes authorized read-only requests to cached monitoring data.
type API struct {
	view    ViewProvider
	options Options
	pollMu  sync.Mutex
	polls   map[[sha256.Size]byte]*pollState
}

type pollState struct {
	mu          sync.Mutex
	version     uint64
	initialized bool
	generation  string
	cursor      string
	lastFull    time.Time
	known       map[string]struct{}
}

type pollStateSnapshot struct {
	version     uint64
	initialized bool
	generation  string
	cursor      string
	lastFull    time.Time
	known       map[string]struct{}
}

type pollEnvelope struct {
	SchemaVersion int       `json:"schema_version"`
	Mode          string    `json:"mode"`
	Reason        string    `json:"reason,omitempty"`
	Generation    string    `json:"generation"`
	Cursor        string    `json:"cursor"`
	CapturedAt    time.Time `json:"captured_at"`
	Sources       any       `json:"sources"`
}

type sparseSource struct {
	Name    string               `json:"name"`
	Status  cache.SourceStatus   `json:"status"`
	Metrics []cache.MetricRecord `json:"metrics"`
}

// New returns a cache-only HTTP handler that obtains one current runtime generation per request.
func New(view ViewProvider, options Options) http.Handler {
	if options.HeartbeatInterval <= 0 {
		options.HeartbeatInterval = 15 * time.Second
	}
	if options.Now == nil {
		options.Now = time.Now
	}
	api := &API{view: view, options: options, polls: make(map[[sha256.Size]byte]*pollState)}
	handler := http.Handler(http.HandlerFunc(api.serve))
	if options.Logger != nil {
		handler = accessLogger(options.Logger, handler)
	}
	return handler
}

type responseStatus struct {
	http.ResponseWriter
	status int
}

// WriteHeader records the first response status before forwarding it.
func (w *responseStatus) WriteHeader(status int) {
	if w.status != 0 {
		return
	}
	w.status = status
	w.ResponseWriter.WriteHeader(status)
}

// Write records an implicit success status before forwarding the body.
func (w *responseStatus) Write(body []byte) (int, error) {
	if w.status == 0 {
		w.WriteHeader(http.StatusOK)
	}
	return w.ResponseWriter.Write(body)
}

// Unwrap exposes the underlying writer to standard HTTP response controllers.
func (w *responseStatus) Unwrap() http.ResponseWriter { return w.ResponseWriter }

// accessLogger records request metadata without headers, credentials, query strings, or response bodies.
func accessLogger(logger *slog.Logger, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		tracked := &responseStatus{ResponseWriter: w}
		next.ServeHTTP(tracked, r)
		status := tracked.status
		if status == 0 {
			status = http.StatusOK
		}
		client := r.RemoteAddr
		if host, _, err := net.SplitHostPort(r.RemoteAddr); err == nil {
			client = host
		}
		logger.Info("http request", "method", r.Method, "path", r.URL.EscapedPath(), "status", status, "client", client, "duration", time.Since(start))
	})
}

// serve loads one generation, enforces its client and bearer policy, and routes one read-only request.
func (a *API) serve(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	w.Header().Set("X-Content-Type-Options", "nosniff")
	w.Header().Set("Cache-Control", "no-store")

	view := a.view()
	if view.Store == nil || !clientAllowed(r.RemoteAddr, view.AllowedClients) {
		writeError(w, http.StatusForbidden, "forbidden")
		return
	}
	tokenDigest, authenticated := bearerIdentity(r.Header.Values("Authorization"), view.TokenDigests)
	if !authenticated {
		w.Header().Set("WWW-Authenticate", `Bearer realm="automation-gateway"`)
		writeError(w, http.StatusUnauthorized, "unauthorized")
		return
	}
	if r.Method != http.MethodGet {
		w.Header().Set("Allow", http.MethodGet)
		writeError(w, http.StatusMethodNotAllowed, "method not allowed")
		return
	}

	path := strings.TrimSuffix(r.URL.Path, "/")
	switch path {
	case "/api/v1/health":
		a.health(w, view.Store, view.CertificateNotAfter)
		return
	case "/api/v1/sources":
		a.sources(w, view.Store)
		return
	case "/api/v1/metrics":
		a.allMetrics(w, view.Store)
		return
	case "/api/v1/metrics/all":
		writeJSON(w, http.StatusOK, view.Store.Full())
		return
	case "/api/v1/metrics/delta":
		a.deltaMetrics(w, r, view.Store)
		return
	case "/api/v1/metrics/poll":
		a.pollMetrics(w, view, tokenDigest)
		return
	case "/api/v1/status":
		a.status(w, view.Status)
		return
	case "/api/v1/status/events":
		a.statusEvents(w, r, view.Status)
		return
	}
	const prefix = "/api/v1/sources/"
	if strings.HasPrefix(path, prefix) {
		rest := strings.TrimPrefix(path, prefix)
		parts := strings.Split(rest, "/")
		if len(parts) == 1 && parts[0] != "" {
			a.source(w, view.Store, parts[0], false, false)
			return
		}
		if len(parts) == 2 && parts[0] != "" && parts[1] == "metrics" {
			a.source(w, view.Store, parts[0], true, false)
			return
		}
		if len(parts) == 2 && parts[0] != "" && parts[1] == "discovery" {
			a.source(w, view.Store, parts[0], false, true)
			return
		}
	}
	writeError(w, http.StatusNotFound, "not found")
}

// clientAllowed reports whether RemoteAddr's actual TCP peer belongs to one configured prefix.
func clientAllowed(remoteAddress string, allowed []netip.Prefix) bool {
	host, _, err := net.SplitHostPort(remoteAddress)
	if err != nil {
		return false
	}
	address, err := netip.ParseAddr(host)
	if err != nil {
		return false
	}
	address = address.Unmap()
	for _, prefix := range allowed {
		if prefix.Contains(address) {
			return true
		}
	}
	return false
}

// validBearer requires one header with a Bearer scheme, ASCII-space separator, and one matching precomputed digest.
func validBearer(headers []string, expected [][sha256.Size]byte) bool {
	_, valid := bearerIdentity(headers, expected)
	return valid
}

// bearerIdentity authenticates one bearer and returns only its stable SHA-256 identity.
func bearerIdentity(headers []string, expected [][sha256.Size]byte) ([sha256.Size]byte, bool) {
	var zero [sha256.Size]byte
	if len(headers) != 1 || len(expected) == 0 {
		return zero, false
	}
	header := headers[0]
	separator := strings.IndexByte(header, ' ')
	if separator <= 0 || !strings.EqualFold(header[:separator], "Bearer") {
		return zero, false
	}
	credentialStart := separator
	for credentialStart < len(header) && header[credentialStart] == ' ' {
		credentialStart++
	}
	if credentialStart == len(header) {
		return zero, false
	}
	candidate := header[credentialStart:]
	for _, r := range candidate {
		if r < 0x21 || r == 0x7f || r == ',' {
			return zero, false
		}
	}
	candidateDigest := sha256.Sum256([]byte(candidate))
	matched := 0
	// Evaluate every configured digest so token position never determines loop length.
	for _, tokenDigest := range expected {
		matched |= subtle.ConstantTimeCompare(candidateDigest[:], tokenDigest[:])
	}
	return candidateDigest, matched == 1
}

// health writes gateway status derived from the selected generation's source snapshots.
func (a *API) health(w http.ResponseWriter, store *cache.Store, certificateNotAfter time.Time) {
	status := "ok"
	code := http.StatusOK
	all := store.All()
	if len(all) == 0 {
		status = "failed"
		code = http.StatusServiceUnavailable
	} else {
		for _, snapshot := range all {
			if !snapshot.Available || snapshot.Stale {
				status = "degraded"
				break
			}
		}
	}
	body := map[string]any{"status": status, "version": a.options.Version}
	if !certificateNotAfter.IsZero() {
		body["certificate_not_after"] = certificateNotAfter.UTC()
	}
	writeJSON(w, code, body)
}

// sources writes a compact JSON summary of every source in store.
func (a *API) sources(w http.ResponseWriter, store *cache.Store) {
	type summary struct {
		Name      string `json:"name"`
		Driver    string `json:"driver"`
		Available bool   `json:"available"`
		Stale     bool   `json:"stale"`
	}
	all := store.All()
	out := make([]summary, 0, len(all))
	for _, snapshot := range all {
		out = append(out, summary{snapshot.Name, snapshot.Driver, snapshot.Available, snapshot.Stale})
	}
	writeJSON(w, http.StatusOK, map[string]any{"sources": out})
}

// source writes status, metrics, or discovery JSON from store, or a not-found error when name is unknown.
func (a *API) source(w http.ResponseWriter, store *cache.Store, name string, metricsOnly, discovery bool) {
	snapshot, ok := store.Snapshot(name)
	if !ok {
		writeError(w, http.StatusNotFound, "source not found")
		return
	}
	if discovery {
		writeJSON(w, http.StatusOK, map[string]any{"source": name, "discovery": snapshot.Discovery})
		return
	}
	if metricsOnly {
		writeJSON(w, http.StatusOK, map[string]any{
			"source": name, "available": snapshot.Available, "stale": snapshot.Stale,
			"last_attempt": snapshot.LastAttempt, "last_success": snapshot.LastSuccess,
			"error": snapshot.Error, "metrics": snapshot.Metrics,
		})
		return
	}
	writeJSON(w, http.StatusOK, snapshot)
}

// allMetrics writes an object mapping every source name in store to its current snapshot.
func (a *API) allMetrics(w http.ResponseWriter, store *cache.Store) {
	out := map[string]cache.Snapshot{}
	for _, snapshot := range store.All() {
		out[snapshot.Name] = snapshot
	}
	writeJSON(w, http.StatusOK, out)
}

// deltaMetrics validates the sole cursor parameter and maps replay failures to explicit recovery statuses.
func (a *API) deltaMetrics(w http.ResponseWriter, r *http.Request, store *cache.Store) {
	values, present := r.URL.Query()["since"]
	if !present || len(values) == 0 || values[0] == "" {
		writeError(w, http.StatusBadRequest, "since is required")
		return
	}
	if len(values) != 1 {
		writeError(w, http.StatusBadRequest, "since must appear once")
		return
	}
	response, err := store.Delta(values[0])
	if err == nil {
		writeJSON(w, http.StatusOK, response)
		return
	}
	switch {
	case errors.Is(err, cache.ErrCursorMalformed):
		writeError(w, http.StatusBadRequest, "invalid cursor")
	case errors.Is(err, cache.ErrCursorExpired):
		writeError(w, http.StatusGone, "cursor expired")
	case errors.Is(err, cache.ErrCursorGeneration):
		writeJSON(w, http.StatusConflict, map[string]any{"error": "reset_required", "reset_required": true})
	case errors.Is(err, cache.ErrCursorFuture):
		writeError(w, http.StatusConflict, "cursor is in the future")
	default:
		writeError(w, http.StatusInternalServerError, "delta unavailable")
	}
}

// pollMetrics computes one authenticated reader response without holding its lock across I/O and commits progress after a successful local write and flush.
func (a *API) pollMetrics(w http.ResponseWriter, view View, identity [sha256.Size]byte) {
	state := a.pollState(identity, view.TokenDigests)
	state.mu.Lock()
	previous := pollStateSnapshot{version: state.version, initialized: state.initialized, generation: state.generation, cursor: state.cursor, lastFull: state.lastFull, known: cloneIdentitySet(state.known)}
	state.mu.Unlock()
	now := a.options.Now().UTC()
	interval := view.PollFullInterval
	if interval <= 0 {
		interval = 10 * time.Minute
	}
	response, next, err := buildPollResponse(view.Store, previous, now, interval)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "poll delta unavailable")
		return
	}
	if err := writePollJSON(w, response); err != nil {
		return
	}
	state.mu.Lock()
	if state.version == previous.version {
		state.initialized = next.initialized
		state.generation = next.generation
		state.cursor = next.cursor
		state.lastFull = next.lastFull
		state.known = cloneIdentitySet(next.known)
		state.version++
	}
	state.mu.Unlock()
}

func buildPollResponse(store *cache.Store, previous pollStateSnapshot, now time.Time, interval time.Duration) (pollEnvelope, pollStateSnapshot, error) {
	if !previous.initialized {
		response, next := buildPollFull(store, previous, "first_request", now)
		return response, next, nil
	}
	if now.Sub(previous.lastFull) >= interval {
		response, next := buildPollFull(store, previous, "periodic", now)
		return response, next, nil
	}

	latest := make(map[string]*sparseSource)
	cursor := previous.cursor
	for {
		delta, err := store.Delta(cursor)
		if err != nil {
			if errors.Is(err, cache.ErrCursorGeneration) || errors.Is(err, cache.ErrCursorExpired) || errors.Is(err, cache.ErrCursorFuture) {
				response, next := buildPollFull(store, previous, "reset_required", now)
				return response, next, nil
			}
			return pollEnvelope{}, previous, err
		}
		for _, transaction := range delta.Transactions {
			if transaction.DiscoveryChanged {
				response, next := buildPollFull(store, previous, "discovery_changed", now)
				return response, next, nil
			}
			for _, record := range transaction.Metrics {
				if record.Operation == "remove" {
					response, next := buildPollFull(store, previous, "metric_removed", now)
					return response, next, nil
				}
				if record.Operation == "upsert" {
					if _, known := previous.known[metricIdentityKey(transaction.Source, record.Identity)]; !known {
						response, next := buildPollFull(store, previous, "metric_added", now)
						return response, next, nil
					}
				}
			}
			source := latest[transaction.Source]
			if source == nil {
				source = &sparseSource{Name: transaction.Source, Metrics: []cache.MetricRecord{}}
				latest[transaction.Source] = source
			}
			source.Status = transaction.Status
			byIdentity := make(map[string]cache.MetricRecord, len(source.Metrics)+len(transaction.Metrics))
			for _, record := range source.Metrics {
				byIdentity[record.Identity] = record
			}
			for _, record := range transaction.Metrics {
				byIdentity[record.Identity] = record
			}
			keys := make([]string, 0, len(byIdentity))
			for key := range byIdentity {
				keys = append(keys, key)
			}
			sort.Strings(keys)
			source.Metrics = source.Metrics[:0]
			for _, key := range keys {
				source.Metrics = append(source.Metrics, byIdentity[key])
			}
		}
		cursor = delta.NextCursor
		if !delta.HasMore {
			break
		}
	}
	names := make([]string, 0, len(latest))
	for name := range latest {
		names = append(names, name)
	}
	sort.Strings(names)
	sources := make([]sparseSource, 0, len(names))
	for _, name := range names {
		sources = append(sources, *latest[name])
	}
	next := previous
	next.cursor = cursor
	response := pollEnvelope{SchemaVersion: 1, Mode: "sparse", Generation: previous.generation, Cursor: cursor, CapturedAt: now, Sources: sources}
	return response, next, nil
}

func buildPollFull(store *cache.Store, previous pollStateSnapshot, reason string, now time.Time) (pollEnvelope, pollStateSnapshot) {
	full := store.Full()
	next := previous
	next.initialized = true
	next.generation = full.Generation
	next.cursor = full.Cursor
	next.lastFull = now
	next.known = make(map[string]struct{})
	for _, source := range full.Sources {
		for _, metric := range source.Metrics {
			identity := metric.Identity
			if identity == "" {
				identity = metric.Name
			}
			next.known[metricIdentityKey(source.Name, identity)] = struct{}{}
		}
	}
	return pollEnvelope{SchemaVersion: 1, Mode: "full", Reason: reason, Generation: full.Generation, Cursor: full.Cursor, CapturedAt: full.CapturedAt, Sources: full.Sources}, next
}

func metricIdentityKey(source, identity string) string {
	return source + "\x00" + identity
}

func cloneIdentitySet(in map[string]struct{}) map[string]struct{} {
	if in == nil {
		return nil
	}
	out := make(map[string]struct{}, len(in))
	for identity := range in {
		out[identity] = struct{}{}
	}
	return out
}

func writePollJSON(w http.ResponseWriter, response pollEnvelope) error {
	body, err := json.Marshal(response)
	if err != nil {
		return err
	}
	body = append(body, '\n')
	w.WriteHeader(http.StatusOK)
	written, err := w.Write(body)
	if err != nil {
		return err
	}
	if written != len(body) {
		return io.ErrShortWrite
	}
	return http.NewResponseController(w).Flush()
}

func (a *API) pollState(identity [sha256.Size]byte, configured [][sha256.Size]byte) *pollState {
	a.pollMu.Lock()
	defer a.pollMu.Unlock()
	allowed := make(map[[sha256.Size]byte]struct{}, len(configured))
	for _, digest := range configured {
		allowed[digest] = struct{}{}
	}
	for digest := range a.polls {
		if _, ok := allowed[digest]; !ok {
			delete(a.polls, digest)
		}
	}
	state := a.polls[identity]
	if state == nil {
		state = &pollState{}
		a.polls[identity] = state
	}
	return state
}

// status writes the current canonical gateway and collector activity snapshot.
func (a *API) status(w http.ResponseWriter, hub *statusmodel.Hub) {
	if hub == nil {
		writeError(w, http.StatusServiceUnavailable, "status unavailable")
		return
	}
	writeJSON(w, http.StatusOK, hub.Snapshot())
}

// statusEvents streams complete status snapshots on every coalesced change and emits keepalive heartbeats.
func (a *API) statusEvents(w http.ResponseWriter, r *http.Request, hub *statusmodel.Hub) {
	if hub == nil {
		writeError(w, http.StatusServiceUnavailable, "status unavailable")
		return
	}
	changes, unsubscribe, err := hub.Subscribe()
	if err != nil {
		if errors.Is(err, statusmodel.ErrTooManySubscribers) {
			writeError(w, http.StatusServiceUnavailable, "too many status streams")
			return
		}
		writeError(w, http.StatusServiceUnavailable, "status unavailable")
		return
	}
	defer unsubscribe()

	w.Header().Set("Content-Type", "text/event-stream")
	w.Header().Set("Cache-Control", "no-store")
	w.Header().Set("X-Accel-Buffering", "no")
	w.WriteHeader(http.StatusOK)
	controller := http.NewResponseController(w)
	if err := writeStatusEvent(w, controller, hub.Snapshot()); err != nil {
		return
	}

	heartbeat := time.NewTicker(a.options.HeartbeatInterval)
	defer heartbeat.Stop()
	for {
		select {
		case <-r.Context().Done():
			return
		case _, open := <-changes:
			if !open {
				return
			}
			if err := writeStatusEvent(w, controller, hub.Snapshot()); err != nil {
				return
			}
		case <-heartbeat.C:
			if err := prepareStreamWrite(controller); err != nil {
				return
			}
			if _, err := fmt.Fprint(w, ": heartbeat\n\n"); err != nil {
				return
			}
			if err := flushStreamWrite(controller); err != nil {
				return
			}
		}
	}
}

func writeStatusEvent(w http.ResponseWriter, controller *http.ResponseController, snapshot statusmodel.Snapshot) error {
	body, err := json.Marshal(snapshot)
	if err != nil {
		return err
	}
	if err := prepareStreamWrite(controller); err != nil {
		return err
	}
	if _, err := fmt.Fprintf(w, "id: %s\nevent: status\ndata: %s\n\n", strconv.FormatUint(snapshot.Sequence, 10), body); err != nil {
		return err
	}
	return flushStreamWrite(controller)
}

func prepareStreamWrite(controller *http.ResponseController) error {
	return controller.SetWriteDeadline(time.Now().Add(5 * time.Second))
}

// flushStreamWrite completes one bounded write and clears its deadline while the stream is idle.
func flushStreamWrite(controller *http.ResponseController) error {
	if err := controller.Flush(); err != nil {
		return err
	}
	return controller.SetWriteDeadline(time.Time{})
}

// writeJSON sends code and JSON-encodes value; encoding errors cannot be returned after headers commit.
func writeJSON(w http.ResponseWriter, code int, value any) {
	w.WriteHeader(code)
	_ = json.NewEncoder(w).Encode(value)
}

// writeError sends message in the standard JSON error envelope.
func writeError(w http.ResponseWriter, code int, message string) {
	writeJSON(w, code, map[string]string{"error": message})
}
